ence",[212]="A Meal Served Cold\031Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.\0311141\0311141\031\031\0311519\031classic-reference",[213]="Hostile Takeover\031Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.\031737\031737\031\031\03133\031classic-reference",[2138]="Cleansing of the Infected\031Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.\0313701\0313701\0312118\0312139\031148\031classic-reference",[2139]="Tharnariun's Hope\031Find and kill the Den Mother.\0313701\0313701\0312138\031\031148\031classic-reference",[214]="Red Silk Bandanas\031Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.\031820\031820\031155\031\0311581\031classic-reference",[215]="Jungle Secrets\031Speak with Lieutenant Doren at the Rebel Camp.\031738\031469\031\031200\03133\031classic-reference",[2158]="Rest and Relaxation\031Speak with Innkeeper Farley at the Lion's Pride Inn.\0316774\031295\031\031\03112\031classic-reference",[2159]="Dolanaar Delivery\031Bring the Dolanaar Delivery to Innkeeper Keldamyr.\0316780\0316736\031\031\031141\031classic-reference",[216]="Between a Rock and a Thistlefur\031Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.\03112757\03112757\031\0316621\031331\031classic-reference",[2160]="Supplies to Tannok\031Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.\0316782\0316806\031\031\0311\031classic-reference",[2161]="A Peon's Burden\031Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.\0316786\0316928\031\031\03114\031classic-reference",[217]="In Defense of the King's Lands\031Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.\0311092\0311092\031263\031\03138\0